//! Differential test: the Rust `Reward` port must match the windv2 `FeesVotingReward` and
//! `BribeVotingReward` exactly.
//!
//! Vectors are generated by `diff-tests/` (Foundry) from the real contracts, deployed with mocks for
//! the voter, voting escrow and reward tokens:
//! `cd diff-tests && forge test --match-test testGenerateRewards`
//!
//! The file is replayed in order. Line field 1 selects the contract (`F` fees, `B` bribe). Each line
//! carries its inputs, the Solidity outcome (`ok` or `err` with a reason) and, after state-changing
//! calls, the full state. Every line is checked against the Rust port.

use std::collections::BTreeMap;
use std::fs;
use std::path::PathBuf;

use windswap_engine::error::Result as MathResult;
use windswap_engine::rewards::{epoch_start, Reward, RewardToken};
use windswap_engine::{MathError, U256};

/// Reward tokens `t0..t4` as named by the generator.
const TOKENS: [&str; 5] = ["t0", "t1", "t2", "t3", "t4"];
/// veNFT token ids `1..=6`.
const NUM_IDS: u64 = 6;

fn read_vectors() -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../diff-tests/vectors")
        .join("rewards.txt");
    fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()))
}

fn u(s: &str) -> U256 {
    s.parse().unwrap()
}

fn n(s: &str) -> u64 {
    s.parse().unwrap()
}

/// The state as the generator logs it: `totalSupply,supplyNumCheckpoints,rewardsListLength,isRewardBits,`
/// `balanceOf(1..6),numCheckpoints(1..6),lastEarn(t0,1..6)...lastEarn(t4,1..6),tokenRewardsPerEpoch(t0..t4)`.
fn state(r: &Reward, now: u64) -> String {
    let mut p: Vec<String> = vec![
        r.total_supply.to_string(),
        r.supply_num_checkpoints().to_string(),
        r.rewards_list_length().to_string(),
    ];
    p.push(
        TOKENS
            .iter()
            .map(|t| if r.is_reward(t) { '1' } else { '0' })
            .collect(),
    );
    p.extend((1..=NUM_IDS).map(|id| r.balance_of(id).to_string()));
    p.extend((1..=NUM_IDS).map(|id| r.num_checkpoints(id).to_string()));
    for t in TOKENS {
        p.extend((1..=NUM_IDS).map(|id| r.last_earn(t, id).to_string()));
    }
    p.extend(
        TOKENS
            .iter()
            .map(|t| r.token_rewards_per_epoch(t, epoch_start(now)).to_string()),
    );
    p.join(",")
}

/// Whether a Rust error matches the reason the Solidity call reverted with.
/// `Panic17` is Solidity's arithmetic panic (overflow or underflow). The revert data does not say
/// which, so either Rust error is accepted.
fn reason_matches(reason: &str, err: MathError) -> bool {
    match reason {
        "Panic17" => matches!(err, MathError::Overflow | MathError::Underflow),
        "NotAuthorized" => err == MathError::NotAuthorized,
        "NotGauge" => err == MathError::NotGauge,
        "InvalidReward" => err == MathError::InvalidReward,
        "NotWhitelisted" => err == MathError::NotWhitelisted,
        "ZeroAmount" => err == MathError::ZeroAmount,
        _ => false,
    }
}

/// `ok` (the call must succeed) or `err|reason` (it must fail with that reason).
fn settle(line: &str, status: &str, reason: &str, res: MathResult<()>, t: &mut Tally, op: &str) {
    match status {
        "ok" => {
            assert_eq!(res, Ok(()), "{line}");
            t.bump(&format!("{op}.ok"));
        }
        "err" => {
            let e = res.expect_err(line);
            assert!(reason_matches(reason, e), "{line}: Rust returned {e:?}");
            t.bump(&format!("{op}.err.{reason}"));
        }
        other => panic!("bad status {other}: {line}"),
    }
}

/// `t0=<amount>;...;t4=<amount>` from the generator.
fn parse_payouts(s: &str) -> BTreeMap<String, U256> {
    s.split(';')
        .map(|kv| {
            let (k, v) = kv.split_once('=').unwrap();
            (k.to_owned(), u(v))
        })
        .collect()
}

#[derive(Default)]
struct Tally(BTreeMap<String, usize>);

impl Tally {
    fn bump(&mut self, key: &str) {
        *self.0.entry(key.to_owned()).or_default() += 1;
    }

    fn get(&self, key: &str) -> usize {
        self.0.get(key).copied().unwrap_or(0)
    }
}

/// Replays `rewards.txt`. Each line's Solidity outcome and post-state must match the Rust port.
#[test]
fn rewards_stateful_replay() {
    let text = read_vectors();
    let mut lines = text.lines().filter(|l| !l.is_empty());

    // Two init lines: fees (F) then bribe (B).
    let mut contracts: BTreeMap<String, Reward> = BTreeMap::new();
    for _ in 0..2 {
        let line = lines.next().expect("missing init line");
        let f: Vec<&str> = line.split('|').collect();
        assert_eq!(f[0], "init", "{line}");
        let rewards: Vec<RewardToken> = f[3].split(',').map(str::to_owned).collect();
        let r = Reward::new(&rewards);
        assert_eq!(state(&r, n(f[2])), f[4], "{line}");
        contracts.insert(f[1].to_owned(), r);
    }

    let mut t = Tally::default();
    for line in lines {
        let f: Vec<&str> = line.split('|').collect();
        let r = contracts
            .get_mut(f[1])
            .unwrap_or_else(|| panic!("unknown contract in {line}"));
        let op = format!("{}.{}", f[0], f[1]);
        match f[0] {
            "deposit" | "withdraw" => {
                let now = n(f[2]);
                let (tid, amount, auth) = (n(f[3]), u(f[4]), f[5] == "1");
                let res = if f[0] == "deposit" {
                    r.deposit(amount, tid, now, auth)
                } else {
                    r.withdraw(amount, tid, now, auth)
                };
                settle(line, f[6], f[7], res, &mut t, &op);
                assert_eq!(state(r, now), f[8], "state after {line}");
            }
            "notify" => {
                let now = n(f[2]);
                let (token, amount, flag) = (f[3], u(f[4]), f[5] == "1");
                let res = if f[1] == "F" {
                    r.notify_fees_reward(token, amount, now, flag)
                } else {
                    r.notify_bribe_reward(token, amount, now, flag)
                };
                settle(line, f[6], f[7], res, &mut t, &op);
                assert_eq!(state(r, now), f[8], "state after {line}");
            }
            "getreward" => {
                let now = n(f[2]);
                let tid = n(f[3]);
                let tokens: Vec<RewardToken> = f[4].split(',').map(str::to_owned).collect();
                let (approved_or_owner, is_voter) = (f[6] == "1", f[5] == "v");
                let res = r.get_reward(tid, &tokens, now, approved_or_owner, is_voter);
                match f[7] {
                    "ok" => {
                        let claims = res.unwrap_or_else(|e| panic!("{line}: Rust returned {e:?}"));
                        let expected = parse_payouts(f[8]);
                        let mut total = U256::ZERO;
                        for tok in TOKENS {
                            // Solidity reports the owner's balance delta per token, so a token listed
                            // twice shows the sum of its two entries.
                            let got = claims
                                .iter()
                                .filter(|(c, _)| c.as_str() == tok)
                                .try_fold(U256::ZERO, |acc, (_, v)| acc.checked_add(*v))
                                .expect("payout sum overflow");
                            assert_eq!(got, expected[tok], "{line}: payout {tok}");
                            total += got;
                        }
                        t.bump(&format!("{op}.ok"));
                        if total > U256::ZERO {
                            t.bump(&format!("{op}.ok.nonzero"));
                        }
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[8], e), "{line}: Rust returned {e:?}");
                        t.bump(&format!("{op}.err.{}", f[8]));
                    }
                    other => panic!("bad getreward status {other}: {line}"),
                }
                assert_eq!(state(r, now), f[9], "state after {line}");
            }
            "earned" => {
                let now = n(f[2]);
                let res = r.earned(f[3], n(f[4]), now);
                match f[5] {
                    "ok" => {
                        assert_eq!(res, Ok(u(f[6])), "{line}");
                        t.bump(&format!("earned.{}.ok", f[1]));
                    }
                    "err" => {
                        let e = res.expect_err(line);
                        assert!(reason_matches(f[6], e), "{line}: Rust returned {e:?}");
                        t.bump(&format!("earned.{}.err.{}", f[1], f[6]));
                    }
                    other => panic!("bad earned status {other}: {line}"),
                }
            }
            other => panic!("unknown op {other}: {line}"),
        }
    }

    eprintln!("rewards vector counts: {:?}", t.0);
    assert!(t.get("deposit.F.ok") > 100);
    assert!(t.get("deposit.B.ok") > 100);
    assert!(t.get("deposit.F.err.NotAuthorized") > 0);
    assert!(t.get("withdraw.F.err.Panic17") > 0);
    assert!(t.get("withdraw.B.err.Panic17") > 0);
    assert!(t.get("notify.F.ok") > 50);
    assert!(t.get("notify.B.ok") > 50);
    assert!(t.get("notify.F.err.NotGauge") > 0);
    assert!(t.get("notify.F.err.InvalidReward") > 0);
    assert!(t.get("notify.B.err.NotWhitelisted") > 0);
    assert!(t.get("notify.F.err.ZeroAmount") > 0);
    assert!(t.get("notify.B.err.ZeroAmount") > 0);
    assert!(t.get("getreward.F.ok.nonzero") > 50);
    assert!(t.get("getreward.B.ok.nonzero") > 20);
    assert!(t.get("getreward.F.err.NotAuthorized") > 0);
    assert!(t.get("earned.F.ok") > 100);
    assert!(t.get("earned.B.ok") > 100);
    assert!(t.get("earned.F.err.Panic17") + t.get("earned.B.err.Panic17") > 0);
}
